const UNDO={st:[],rd:[],last:null,busy:false,t:0};const UNSKIP=['tab','_projOpen','_delArm','nestSel','nestTapOn','nestMoveOn','setup'];
function undoSnap(){if(UNDO.busy)return;clearTimeout(UNDO.t);UNDO.t=setTimeout(()=>{try{const o={};for(const k in S)if(!UNSKIP.includes(k)&&!['ref','meshT','_hm','cylMap'].includes(k))o[k]=S[k];const j=JSON.stringify(o);if(j===UNDO.last)return;if(UNDO.last!=null){UNDO.st.push(UNDO.last);if(UNDO.st.length>40)UNDO.st.shift();UNDO.rd.length=0;}UNDO.last=j;undoBtns();}catch(e){}},350);}
function undoApply(j){UNDO.busy=true;try{const o=JSON.parse(j);for(const k of Object.keys(S))if(!UNSKIP.includes(k)&&!['ref','meshT','_hm','cylMap'].includes(k))delete S[k];Object.assign(S,o);UNDO.last=j;MODEL=null;S._hm=null;SIMSTATE.dirty=true;buildProgram();render();}finally{UNDO.busy=false;}undoBtns();}
function undo(){if(!UNDO.st.length){toast(LANG==='vi'?'Không còn gì để hoàn tác':'Nothing to undo');return;}UNDO.rd.push(UNDO.last);undoApply(UNDO.st.pop());toast(LANG==='vi'?'Đã hoàn tác':'Undone');}
function redo(){if(!UNDO.rd.length){toast(LANG==='vi'?'Không còn gì để làm lại':'Nothing to redo');return;}UNDO.st.push(UNDO.last);undoApply(UNDO.rd.pop());toast(LANG==='vi'?'Đã làm lại':'Redone');}
function undoBtns(){const u=document.getElementById('btnUndo'),r=document.getElementById('btnRedo');if(u)u.style.opacity=UNDO.st.length?1:0.35;if(r)r.style.opacity=UNDO.rd.length?1:0.35;}
function persist(){try{localStorage.setItem('trakcam',JSON.stringify({...S,ref:null,meshT:null,_hm:null,cylMap:null}));}catch(e){}undoSnap();}
function restore(){try{const j=JSON.parse(localStorage.getItem('trakcam')||'null');if(j&&j.tools){Object.assign(S,j);S.tab=S.tab||'program';try{document.body.classList.toggle('gwrap',S.gwrap!==false);}catch(e){}return true;}}catch(e){}return false;}

