 er16:{en:'ER16 collet chuck',vi:'Bầu kẹp collet ER16',max:0.394,d:1.1,len:2.2,runout:0.0004,gauge:2.75,kind:'er',why:['Small tools to 10 mm (3/8"). Slim nose reaches into tight spots; good runout with a quality collet.','Dao nhỏ tới 10 mm (3/8"). Đầu thon, vào được chỗ hẹp; độ đảo tốt nếu collet tốt.']},
 er32:{en:'ER32 collet chuck',vi:'Bầu kẹp collet ER32',max:0.787,d:1.97,len:2.4,runout:0.0004,gauge:2.75,kind:'er',why:['Most common shop holder: one chuck takes 1/8"–3/4" tools by changing the collet. Fine for drills, spot drills, small end mills.','Bầu kẹp phổ biến nhất: một bầu kẹp dao 1/8"–3/4" chỉ cần đổi collet. Dùng tốt cho mũi khoan, khoan mồi, dao phay nhỏ.']},
 er20:{en:'ER20 collet chuck',vi:'Bầu kẹp collet ER20',max:0.512,d:1.34,len:2.3,kind:'er',runout:0.0004,gauge:2.75,why:['Tools to 13 mm (1/2"): a good middle size, slimmer than ER32.','Dao tới 13 mm (1/2"): cỡ giữa, thon hơn ER32.']},
 er25:{en:'ER25 collet chuck',vi:'Bầu kẹp collet ER25',max:0.630,d:1.65,len:2.4,kind:'er',runout:0.0004,gauge:2.75,why:['Tools to 16 mm (5/8"); common on BT30 and small machines.','Dao tới 16 mm (5/8"); hay dùng trên máy côn BT30 và máy nhỏ.']},
 er40:{en:'ER40 collet chuck',vi:'Bầu kẹp collet ER40',max:1.024,d:2.48,len:2.6,runout:0.0004,gauge:3.15,kind:'er',why:['Bigger ER for tools up to 1". More grip than ER32, bulkier nose.','ER lớn cho dao tới 1". Kẹp chắc hơn ER32, đầu to hơn.']},
 shrink:{en:'Shrink-fit holder',vi:'Bầu kẹp co nhiệt (shrink fit)',max:1.0,d:1.2,len:3.2,runout:0.0001,gauge:3.5,kind:'shrink',why:['Heated, then shrinks onto the shank: best runout (<.0001") and very slim — great for finishing, 3D and high RPM. Needs a shrink machine.','Nung nóng rồi co lại ôm cán dao: độ đảo tốt nhất (<.0001") và rất thon — tốt cho phay tinh, 3D và RPM cao. Cần máy co nhiệt.']},
 hydraulic:{en:'Hydraulic chuck',vi:'Bầu kẹp thủy lực',max:1.25,d:1.8,len:3.1,runout:0.0001,gauge:3.15,kind:'mill',why:['Oil pressure grips the shank: excellent runout and damping, quick tool changes with a hex key. Great for finishing and reaming.','Áp lực dầu kẹp cán dao: độ đảo rất tốt và giảm rung, thay dao nhanh bằng lục giác. Tốt cho phay tinh và doa.']},
 milling:{en:'Milling chuck (power chuck)',vi:'Bầu kẹp phay lực (milling chuck)',max:1.25,d:2.6,len:3.4,runout:0.0002,gauge:3.35,kind:'mill',why:['Very high clamping force: heavy roughing and adaptive with big end mills without the tool pulling out.','Lực kẹp rất lớn: phá thô nặng và adaptive với dao lớn mà dao không bị tuột.']},
 weldon:{en:'Side-lock / Weldon holder',vi:'Bầu kẹp vít cạnh (Weldon)',max:1.25,d:1.9,len:2.6,runout:0.0003,gauge:2.5,kind:'weldon',why:['A set screw on the shank flat: the tool can never pull out. Simple and cheap; runout is not as good as shrink or hydraulic.','Vít bắt vào mặt phẳng cán dao: dao không thể tuột. Đơn giản, rẻ; độ đảo không bằng co nhiệt hay thủy lực.']},
 drill:{en:'Drill chuck (keyless / Jacobs)',vi:'Bầu khoan (Jacobs / tự siết)',max:0.5,d:1.9,len:3.4,runout:0.002,gauge:4.25,kind:'drill',why:['Takes any straight-shank drill 0–1/2" fast. Fine for drilling, not for side milling (low grip, more runout).','Kẹp nhanh mọi mũi khoan chuôi thẳng 0–1/2". Dùng để khoan, không dùng phay ngang (kẹp yếu, đảo nhiều).']},
