 const tq=Math.tan(Math.PI/8);const lw=(pts,c)=>{let s='0\nLWPOLYLINE\n8\n0\n90\n'+pts.length+'\n70\n'+(c?1:0)+'\n';for(const p of pts){s+='10\n'+p[0]+'\n20\n'+p[1]+'\n';if(p[2])s+='42\n'+p[2]+'\n';}return s;};
