 const si=Math.max(1,Math.ceil(nx/(SIMSTATE.playing?90:150))),sj=Math.max(1,Math.ceil(nth/(SIMSTATE.playing?72:120)));const base=hexRGB(mat().color),L=[-0.4,-0.5,0.77];
