 const H=sp(L[0]).map(h=>h.toLowerCase()),ix=k=>H.findIndex(h=>k.some(w=>h.includes(w)));const iN=ix(['tool','pocket','no']),iD=ix(['desc','name']),iDia=ix(['diam']),iT=ix(['type']),iF=ix(['flute']),iV=ix(['vendor']),iP=ix(['part']),iNo=ix(['note']);if(iN<0||iDia<0)return 0;let n=0;
