const LKIND={thread:['mill','finish'],tslot:['mill','finish'],surfSpiral:['ball','finish'],surfSteep:['ball','finish'],face:['face','face'],adaptive:['mill','adaptive'],pocket:['mill','rough'],slot:['mill','rough'],rest:['mill','rough'],circ:['mill','adaptive'],spot:['spot','drill'],drill:['drill','drill'],tap:['tap','drill'],ream:['ream','drill'],surfFinish:['ball','finish'],surfWater:['ball','finish'],surfRadial:['ball','finish'],surfScallop:['ball','finish'],surfMorph:['ball','finish'],flow5:['ball','finish'],moulding:['ball','finish'],surfRough:['mill','rough']};
