const DNUM='(\\d*\\.\\d+|\\d+(?:\\.\\d+)?)';
function dclean(t){t=String(t||'').replace(/%%[cC]/g,'Ø').replace(/%%[dD]/g,'°').replace(/%%[pP]/g,'±');t=t.replace(/\\[A-Za-z][^;]*;/g,'').replace(/[{}]/g,'').replace(/\\P/g,' ');return t.split(/\s+/).join(' ').trim();}
