function isoLimits(mm,code){const m=String(code).match(/^([A-Za-z]{1,2})(\d{1,2})$/);if(!m||mm<=0||mm>500)return null;const L=m[1],g=+m[2];if(!FIT_IT[g])return null;const i=FIT_R.findIndex(r=>mm<=r),it=FIT_IT[g][i],lo=L.toLowerCase();
 if(lo==='js')return[-it/2,it/2];if(L===L.toLowerCase()){if(FIT_UP[lo]){const es=FIT_UP[lo][i];return[es-it,es];}if(FIT_LO[lo]){const ei=FIT_LO[lo][i];return[ei,ei+it];}return null;}
 if(L==='H')return[0,it];if(L==='G'||L==='F'){const ei=-FIT_UP[L.toLowerCase()][i];return[ei,ei+it];}return null;}
function fitCalc(nom,code,unit){const mm=unit==='mm'?nom:(nom>=2.5&&unit!=='in'?nom:nom*25.4);const lim=isoLimits(mm,code);if(!lim)return null;const lo=(mm+lim[0]/1000)/25.4,hi=(mm+lim[1]/1000)/25.4;
 return{code,nominal_mm:mm,nominal_in:mm/25.4,lo,hi,mid:(lo+hi)/2,hole:code[0]===code[0].toUpperCase(),um:lim};}
function dFits(notes){const out=[];for(const raw of notes){const u=dclean(raw);for(const m of u.matchAll(/(?:Ø|DIA\s*)?\s*(\d*[.,]\d+|\d+)\s*(?:MM)?\s*([A-HJ-NP-Za-hj-np-z]{1,2}\d{1,2})\b(?!\s*-)/g)){const code=m[2];if(/^(UN|M|X|R|DP)/i.test(code))continue;const f=fitCalc(parseFloat(m[1].replace(',','.')),code,'auto');if(f)out.push({...f,text:m[0].trim()});}}return out;}
function dRa(notes){let best=null;for(const raw of notes){const u=dclean(raw).toUpperCase().replace(/µ/g,'U');for(const m of u.matchAll(new RegExp('(?:RA\\s*'+DNUM+'|'+DNUM+'\\s*(?:√|RA\\b|UIN|MICRO\\s*IN))|√\\s*'+DNUM,'g'))){const v=parseFloat(m[1]||m[2]||m[3]);const um=(v<=6.3&&/RA/.test(m[0])&&!/UIN/.test(u))?v:v*0.0254;if(!best||um<best.um)best={um,uin:Math.round(um/0.0254),text:m[0].trim()};}}return best;}
