const ABRN={A:['Brown aluminum oxide','Nhôm oxit nâu'],WA:['White aluminum oxide','Nhôm oxit trắng'],'32A':['Norton 32A (mono-crystal)','Norton 32A (đơn tinh thể)'],SG:['Seeded-gel ceramic','Gốm SG'],C:['Green silicon carbide','Silic cacbua xanh'],CBN:['Cubic boron nitride','CBN (bo nitrua lập phương)'],D:['Diamond','Kim cương']};
/* score every wheel for this job: abrasive vs material, hardness, finish, machine kind */
function wheelRank(m,hrc,kind,ra){const g=C.mprops(m).group,vi=LANG==='vi',ferr=['steel','stainless','superalloy'].includes(g)||/ss|steel|a2|d2|4140|1018/i.test(m.id),nonf=['castiron','aluminum','copper','plastic'].includes(g);
 return Object.keys(GWI).map(k=>{const w=GWI[k];let sc=50;const why=[];const add=(d,en,vt)=>{sc+=d;why.push((d>0?'+':'')+d+'  '+(vi?vt:en));};
  const seg=/^SEG/.test(k);if(kind==='v'&&!seg)add(-60,'not a segment wheel for a rotary (Blanchard) grinder','không phải đá mảnh cho máy mài quay');if(kind!=='v'&&seg)add(-60,'segments fit only rotary grinders','đá mảnh chỉ dùng máy mài quay');
  if(w.abr==='D'){if(ferr)add(-50,'diamond reacts with steel (carbon dissolves)','kim cương phản ứng với thép');else add(-15,'diamond is for carbide / ceramic','kim cương dành cho hợp kim cứng / gốm');}
  if(w.abr==='C'){if(nonf)add(30,'SiC cuts cast iron & non-ferrous best','SiC mài gang & kim loại màu tốt nhất');else add(-25,'SiC dulls fast on steel','SiC mau cùn trên thép');}
  if(['A','WA','32A','SG'].includes(w.abr)){if(nonf&&g!=='castiron')add(-20,'aluminum oxide loads up on soft non-ferrous','nhôm oxit dễ bám phoi kim loại mềm');else if(g==='castiron')add(-5,'works on cast iron, SiC is better','dùng được cho gang, SiC tốt hơn');else add(15,'aluminum oxide family suits steel','họ nhôm oxit hợp với thép');}
  if(w.abr==='CBN'){if(ferr&&hrc>=58)add(35,'CBN holds size on very hard steel','CBN giữ kích thước trên thép rất cứng');else if(ferr&&hrc>=50)add(5,'CBN works but costs more','CBN dùng được nhưng đắt');else add(-25,'CBN wasted on soft or non-ferrous','CBN phí trên vật liệu mềm / màu');}
  if(ferr){if(hrc<35){if(w.abr==='A')add(20,'tough brown grain for soft steel','hạt nâu dai cho thép mềm');if(['32A','WA'].includes(w.abr))add(5,'friable grain is fine but not needed','hạt dễ vỡ dùng được nhưng không cần');}
   else if(hrc<50){if(w.abr==='WA')add(20,'white friable grain runs cool on 35–50 HRC','hạt trắng dễ vỡ mài mát cho 35–50 HRC');if(w.abr==='A')add(-10,'brown grain burns hardened steel','hạt nâu dễ cháy thép tôi');}
   else{if(['32A','SG'].includes(w.abr))add(20,'mono-crystal / ceramic grain for hard tool steel','hạt đơn tinh thể / gốm cho thép dụng cụ cứng');if(w.abr==='A')add(-20,'brown grain glazes and burns hard steel','hạt nâu bị bóng, cháy thép cứng');}
   if(g==='stainless'&&w.abr==='SG')add(15,'ceramic grain resists loading on stainless','hạt gốm ít bám inox');
   if(hrc>=45&&/[HI]/.test(w.grade))add(5,'soft grade sheds dull grain on hard steel','độ cứng đá mềm, tự thay hạt khi mài thép cứng');}
  if(ra&&ra<=16){if(w.grit>=60&&w.grit<100)add(10,'60 grit reaches Ra ≤ 16 µin','hạt 60 đạt Ra ≤ 16 µin');else if(w.grit<=46)add(-5,'46 grit: needs a fine dress for Ra ≤ 16','hạt 46: cần sửa đá mịn mới đạt Ra ≤ 16');}
  else if(w.grit>=60&&w.grit<100)add(-3,'finer grit removes stock slower','hạt mịn ăn chậm hơn');
  return{k,sc:Math.max(0,Math.min(100,Math.round(sc))),why};}).sort((a,b)=>b.sc-a.sc);}

