const WMAT={a2:1,s4140:1.05,s4340:1.05,s1045:1.05,s1018:1.05,s12l14:1.05,ss303:0.9,ss304:0.9,ss316:0.9,ss174:0.9,ti64:0.8,in718:0.75,al6061:2,al7075:2,al2024:2,al5052:2,mic6:2,cu110:0.55,brass:0.55,brz932:0.55,ci:1};
const SKIMS={0:[1,'±.0005–.001','63–125'],1:[1.5,'±.0003','32–63'],2:[1.8,'±.0002','16–32'],3:[2,'±.0001','8–16']},SK_ST=[0.0035,0.0012,0.0003],SK_GAP=[0.0006,0.0005,0.0004];
function wireOffsets(w,sk){const r=w.dia/2;if(!sk)return[+(r+w.gap).toFixed(5)];const o=[r+SK_GAP[Math.min(sk,3)-1]];for(let k=sk-1;k>0;k--)o.unshift(o[0]+SK_ST[k]);o.unshift(o[0]+SK_ST[0]+(w.gap-SK_GAP[0]));return o.map(v=>+v.toFixed(5));}
function offPoly(P,d){/* d>0 grows a CCW loop */const n=P.length,out=[];for(let i=0;i<n;i++){const a=P[(i-1+n)%n],b=P[i],c=P[(i+1)%n];const n1=[b[1]-a[1],-(b[0]-a[0])],n2=[c[1]-b[1],-(c[0]-b[0])];const l1=Math.hypot(...n1)||1,l2=Math.hypot(...n2)||1;const u1=[n1[0]/l1,n1[1]/l1],u2=[n2[0]/l2,n2[1]/l2];let bx=u1[0]+u2[0],by=u1[1]+u2[1];const bl=Math.hypot(bx,by);
 if(bl<1e-6){out.push([b[0]+u1[0]*d,b[1]+u1[1]*d]);continue;}bx/=bl;by/=bl;const cs=bx*u1[0]+by*u1[1];const k=d/Math.max(cs,0.25);if(cs<0.5){/* sharp convex corner: arc */const a0=Math.atan2(u1[1],u1[0]),a1=Math.atan2(u2[1],u2[0]);let da=a1-a0;while(da>Math.PI)da-=2*Math.PI;while(da<-Math.PI)da+=2*Math.PI;if(da*d>0){const m_=Math.max(2,Math.ceil(Math.abs(da)/0.2));for(let j=0;j<=m_;j++){const t=a0+da*j/m_;out.push([b[0]+Math.cos(t)*d,b[1]+Math.sin(t)*d]);}continue;}}
 out.push([b[0]+bx*k,b[1]+by*k]);}return out;}
function W0(){S.wire={wire:'0.010',skims:2,tab:0.030,startD:0.040,...(S.wire||{})};return S.wire;}
function wireBuild(){const w=W0(),M=mach(),m=mat(),vi=LANG==='vi',WR=WIRES[w.wire]||WIRES['0.010'],H=thick();const OFF=wireOffsets(WR,+w.skims);const f=WMAT[m.id]||1,t=Math.max(0.05,H),tf=t<1?Math.min(1.1,Math.max(0.45,0.55+0.45*t)):Math.min(1.15,1+0.05*(t-1));const rate=16*f*WR.rate*tf;
 const conts=[],warn=[];if(!S.geom)return null;
 for(const ft of S.feats){if(ft.kind==='profile')conts.push({kind:'punch',P:ft.loop,label:vi?'Biên ngoài (punch)':'Outside (punch)',en:'OUTSIDE (PUNCH)'});else if(ft.kind==='pocket'&&ft.through)conts.push({kind:'die',P:ft.loop,label:(vi?'Hốc xuyên ':'Through opening ')+ft.id+' (die)',en:'OPENING '+ft.id+' (DIE)'});
  else if(ft.kind==='holes'&&(ft.through||ft.depth==null))for(const q of ft.pts){if(ft.dia<0.06){warn.push((vi?'Lỗ Ø':'Hole Ø')+f4(ft.dia)+(vi?' nhỏ hơn 0.060 — khoan EDM hoặc khoan thường':' under 0.060 — EDM-drill or drill it'));continue;}conts.push({kind:'die',P:C.circlePts({x:q[0],y:q[1],r:ft.dia/2},0.0002),label:(vi?'Lỗ Ø':'Hole Ø')+f4(ft.dia)+' (die)',en:'HOLE D'+f4(ft.dia)+' (DIE)'});}}
 conts.sort((a,b)=>(a.kind==='punch')-(b.kind==='punch'));
 const ops=[];for(const c of conts){let P=c.P.slice();if(C.area(P)<0)P.reverse();const side=c.kind==='die'?-1:1;const b=C.bbox(P),span=Math.min(b[2]-b[0],b[3]-b[1]);if(c.kind==='die'&&span<2*OFF[0]+0.01){warn.push(c.label+(vi?': quá nhỏ cho dây này':': too small for this wire'));continue;}
  const need=w.startD/2+0.03+OFF[0];let st;if(c.kind==='die'){st=[(b[0]+b[2])/2,(b[1]+b[3])/2];if(!C.pip(st,P)){let best=null;for(let i=0;i<P.length;i+=Math.max(1,P.length>>5)){const q=[P[i][0]+(st[0]-P[i][0])*0.1,P[i][1]+(st[1]-P[i][1])*0.1];if(C.pip(q,P)){best=q;break;}}st=best||st;}}else st=[b[0]-need,(b[1]+b[3])/2];
  const passes=OFF.map(d=>offPoly(P,side*d));let ei=0,bd=1e9;passes[0].forEach((q,i)=>{const dd=Math.hypot(q[0]-st[0],q[1]-st[1]);if(dd<bd){bd=dd;ei=i;}});
  const roll=Q=>Q.slice(ei).concat(Q.slice(0,ei+1));const segL=Q=>{let s=0;for(let i=1;i<Q.length;i++)s+=Math.hypot(Q[i][0]-Q[i-1][0],Q[i][1]-Q[i-1][1]);return s;};
  const R0=roll(passes[0]),tot=segL(R0);let acc=0,ti=R0.length-1;for(let i=1;i<R0.length;i++){acc+=Math.hypot(R0[i][0]-R0[i-1][0],R0[i][1]-R0[i-1][1]);if(acc>tot-w.tab){ti=i;break;}}
  const per=segL(passes[passes.length-1]);ops.push({...c,start:st,entry:R0[0],rough:R0.slice(0,ti),tab:R0.slice(ti-1),skims:passes.slice(1).map(roll),len:tot,time:tot*H/rate*SKIMS[Math.min(3,+w.skims)][0]*60,per});}
 const time=ops.reduce((s,o)=>s+o.time,0);const chk=[];if(H>M.maxThick)chk.push({n:vi?'Chiều dày':'Thickness',c:false,d:`${f4(H)} / ${M.maxThick}`});else chk.push({n:vi?'Chiều dày':'Thickness',c:true,d:`${f4(H)} / ${M.maxThick}`});
 const J={M,m,WR,OFF,rate,ops,warn,time,H,skims:+w.skims,w};J.gcode=wireGcode(J);return J;}
function wireGcode(J){const L=[],ln=s=>L.push(s),vi=LANG==='vi';ln('%');ln('O1000 ('+(S.hdr.name||'PART').toUpperCase().slice(0,28)+')');ln('(MINI CAM WIRE EDM - '+J.M.name.toUpperCase().replace(/[()]/g,'')+')');ln('('+J.WR.name.toUpperCase()+' - '+J.m.en.toUpperCase()+' - THICKNESS '+f4(J.H)+')');
 ln('('+J.skims+' SKIM'+(J.skims===1?'':'S')+' - TOL '+SKIMS[Math.min(3,J.skims)][1]+' - RA '+SKIMS[Math.min(3,J.skims)][2]+')');J.OFF.forEach((d,k)=>ln('(OFFSET '+(k?'SKIM '+k:'ROUGH')+' '+f4(d)+' - WIRE CENTRE PATH, G40)'));ln('(CONDITIONS: S1 ROUGH'+(J.OFF.length>1?', '+J.OFF.slice(1).map((_,k)=>'S'+(k+2)).join(', ')+' SKIMS':'')+' - SET IN THE TECH TABLE)');ln('(X0 Y0 = PART DATUM. START HOLES:)');
 J.ops.forEach(o=>ln('(  '+(o.en||o.label).toUpperCase().slice(0,30)+'  X'+f4(o.start[0])+' Y'+f4(o.start[1])+'  DIA '+f4(J.w.startD)+')'));ln('G90 G40 G17');if(!J.ops.length){ln('M30');ln('%');return L.join('\n');}
 ln('G92 X'+f4(J.ops[0].start[0])+' Y'+f4(J.ops[0].start[1])+' (WIRE AT THE FIRST START HOLE)');let cur=J.ops[0].start.slice();
 const emit=(pts)=>{const prog=[{g:0,x:cur[0],y:cur[1],z:0}].concat(pts.map(p=>({g:1,x:p[0],y:p[1],z:0,f:1})));const fit=C.arcFit(prog,0.00025);for(const b of fit.slice(1)){if(b.g===1)ln('G01 X'+f4(b.x)+' Y'+f4(b.y));else ln('G0'+b.g+' X'+f4(b.x)+' Y'+f4(b.y)+' I'+f4(b.i)+' J'+f4(b.j));cur=[b.x,b.y];}};
 J.ops.forEach((o,n)=>{ln('(--- '+(o.en||o.label).toUpperCase()+' ---)');if(n){ln('G00 X'+f4(o.start[0])+' Y'+f4(o.start[1]));cur=o.start.slice();}ln('M60 (THREAD THE WIRE)');ln('S1 (ROUGH)');emit([o.entry].concat(o.rough));
  ln('M00 (SUPPORT THE '+(o.kind==='die'?'SLUG':'PART')+' - MAGNET OR WEDGE - THEN CYCLE START TO CUT THE TAB)');ln('(TAB: ROUGH)');emit(o.tab);
  o.skims.forEach((Q,k)=>{ln('S'+(k+2)+' (SKIM '+(k+1)+')');const q=k%2===0?Q.slice().reverse():Q;emit(q);});ln('M00 (TAKE THE '+(o.kind==='die'?'SLUG':'PART')+' OUT)');ln('M50 (CUT THE WIRE)');});
 ln('M30');ln('%');return L.join('\n');}
/* ---------- shared UI for grind / wire ---------- */
function mtField(k,lab,v,unit){return`<label class="f">${lab}<input inputmode="decimal" data-mtb="${k}" value="${esc(v)}">${unit?`<span class="sub" style="font-size:12px">${unit}</span>`:''}</label>`;}
function mtChecks(ch){return`<div class="scroll"><table><tbody>${ch.map(x=>`<tr><td>${x.c?'✅':'⚠️'}</td><td><b>${esc(x.n)}</b></td><td>${esc(x.d)}</td></tr>`).join('')}</tbody></table></div>`;}
function mtCode(code){code=gAscii(code).toUpperCase();MTCODE=code;return`<div class="card" style="--cc:#ff6a13"><h2>${t('gcode')}</h2><div class="row" style="margin-bottom:10px"><button class="btn go" data-mt="save">${IC.save}${t('saveFile')}</button><button class="btn" data-mt="copy">${IC.copy}${t('copy')}</button></div><pre class="code">${hlG(code)}</pre></div>`;}
let MTCODE='';
const gAscii=s=>String(s).replace(/Ø/g,'D').replace(/[αΑ]/g,'A').replace(/×/g,'X').replace(/[–—]/g,'-').replace(/°/g,' DEG').replace(/µ/g,'U').replace(/±/g,'+/-').replace(/đ/g,'d').replace(/Đ/g,'D').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\x09\x0a\x0d\x20-\x7e]/g,'');
/* ---------- grinding processes in one tab ---------- */
const GPROC=[['surf',['Surface grind','Mài phẳng'],m=>m.type==='grind'],['od',['Cylindrical OD','Mài tròn ngoài (OD)'],m=>m.type==='cylgrind'&&!m.vertical&&!m.centerless],['id',['Internal ID','Mài lỗ (ID)'],m=>m.type==='cylgrind'&&!m.vertical&&!m.centerless&&m.idRpm],['vg',['Vertical grind','Mài đứng (bàn quay)'],m=>m.vertical]];
function gProc(){const M=mach();if(M.vertical)return'vg';if(M.type==='grind')return'surf';return S.gproc==='id'?'id':'od';}
function gProcBar(){const vi=LANG==='vi',cur=gProc();return`<div class="seg" style="display:flex;flex-wrap:wrap;margin:0 0 12px">${GPROC.map(([k,n])=>`<button class="${k===cur?'on':''}" data-gproc="${k}" style="flex:1 0 auto">${n[vi?1:0]}</button>`).join('')}</div>`;}
function setGProc(k){const P=GPROC.find(x=>x[0]===k);if(!P)return;S.gproc=k;S.lastGP=S.lastGP||{};const M=mach();if(P[2](M)){S.lastGP[k]=M.id;}else{const id=S.lastGP[k]&&C.MACHINES.find(m=>m.id===S.lastGP[k]&&P[2](m))?S.lastGP[k]:(C.MACHINES.find(P[2])||{}).id;if(id){const el=$('#selMachine');el.value=id;el.dispatchEvent(new Event('change',{bubbles:true}));}}
 if(k==='id'||k==='od'){const c=CY0();if(!c.zones.some(z=>z.side===k))c.zones=k==='id'?[{side:'id',dia:0.75,z0:-0.25,z1:-1.25}]:[{side:'od',dia:1.0,z0:-0.5,z1:-2.5}];}
 persist();rGrind();}
/* macro variables you can edit here (or at the machine) */
function mvKey(){return gProc();}
function mvApply(code){const ov=(S.gmv||{})[mvKey()]||{};const vars=[];const out=code.split('\n').map(l=>{const m=l.match(/^#(\d+) = (-?\d*\.?\d+) \((.*)\)$/);if(!m)return l;const n=m[1],v=ov[n]!=null?ov[n]:m[2];vars.push({n,v,def:m[2],c:m[3]});return ov[n]!=null?`#${n} = ${v} (${m[3]})`:l;});return{code:out.join('\n'),vars};}
function mvCard(vars){const vi=LANG==='vi';if(!vars.length)return'';const ov=(S.gmv||{})[mvKey()]||{};
 return`<div class="card" style="--cc:#8b4fd6"><h2>${vi?'Biến macro trong G-code':'Macro variables in the G-code'}</h2><p class="sub" style="margin:0 0 8px;font-size:13px">${vi?'Sửa số ở đây là G-code đổi theo; hoặc sửa thẳng trên máy (macro B) cho chi tiết khác.':'Edit a value here and the G-code follows — or change it at the machine (macro B) for another part.'}</p>
 <div class="scroll"><table style="font-size:13.5px"><tbody>${vars.map(x=>`<tr${ov[x.n]!=null?' style="background:color-mix(in srgb,#8b4fd6 12%,transparent)"':''}><td style="font-family:ui-monospace,Menlo,monospace;white-space:nowrap"><b>#${x.n}</b></td><td><input class="inp" style="width:92px" inputmode="decimal" data-mv="${x.n}" value="${esc(x.v)}"></td><td style="font-size:12.5px">${esc(x.c.toLowerCase())}${ov[x.n]!=null?` <span class="sub">(${vi?'gốc':'was'} ${esc(x.def)})</span>`:''}</td></tr>`).join('')}</tbody></table></div>
 ${Object.keys(ov).length?`<button class="btn sm" data-mt="mvReset" style="margin-top:8px">${vi?'Trả về giá trị app tính':'Back to calculated values'}</button>`:''}</div>`;}
/* ---------- centerless ---------- */
function CL0(){S.cless={d:0.5,len:2,qty:100,stock:0.006,ra:16,hrc:'',mode:'thru',label:0,...(S.cless||{})};return S.cless;}
function clBuild(){const c=CL0(),M=mach(),m=mat(),vi=LANG==='vi',p=C.mprops(m),hrc=c.hrc!==''?+c.hrc:(HARD_DEF[m.id]||0),hard=hrc>=45;const rank=wheelRank(m,hrc,'h',c.ra);const wk=c.wheel&&GW[c.wheel]?c.wheel:rank[0].k,wh=GW[wk];
 const d=+c.d,Lp=+c.len,qty=Math.max(1,+c.qty||1),stock=+c.stock,thru=c.mode!=='in';const sr=safeRpm(M.wheelD,Math.min(6000,wh[2]),wh[2],+c.label||0,M.rpmMax);
 const Vw=hard?100:150,Nr=Math.min(M.regMax||300,Vw*12/(Math.PI*M.regD));const angR=thru?3:0.5,angF=thru?1.25:0.5,fR=Math.PI*M.regD*Nr*Math.sin(angR*Math.PI/180),fF=Math.PI*M.regD*Nr*Math.sin(angF*Math.PI/180)*0.8;
 const perR=hard?0.001:0.002,perF=c.ra<=8?0.0003:0.0005,allow=Math.min(stock,0.001),pR=Math.max(1,Math.ceil((stock-allow)/perR)),pF=Math.max(1,Math.ceil(allow/perF));
 const h=+Math.min(d/2,0.5).toFixed(3),blade=d<0.25?'30° carbide':'30° carbide / 60° for > 1"';
 const ops=[],checks=[];const ok=(n,c_,dd)=>checks.push({n,c:c_,d:dd});
 if(thru){const tR=qty*Lp/fR,tF=qty*Lp/fF;ops.push({kind:'cl',tag:vi?'Xuyên qua (thô)':'Through-feed rough',passes:pR,df:perR,feed:fR,ang:angR,time:pR*tR,steps:[`${vi?'Bánh dẫn':'Reg. wheel'} Ø${M.regD} × ${Math.round(Nr)} rpm → ${Vw} SFM ${vi?'trên chi tiết':'on the work'}`,`Through-feed = π × ${M.regD} × ${Math.round(Nr)} × sin ${angR}° = ${fR.toFixed(1)} in/min`,`${pR} ${vi?'lượt':'passes'} × ${f4(perR)} ${vi?'trên Ø':'on Ø'} (${vi?'chừa':'leave'} ${f4(allow)})`,`${qty} × ${Lp}" ${vi?'nối đuôi nhau':'end-to-end'} → ${tR.toFixed(1)} min ${vi?'mỗi lượt':'per pass'}`]},
  {kind:'cl',tag:vi?'Xuyên qua (tinh)':'Through-feed finish',passes:pF,df:perF,feed:fF,ang:angF,time:pF*tF,steps:[`${vi?'Góc bánh dẫn':'Reg. angle'} ${angF}° → ${fF.toFixed(1)} in/min`,`${pF} × ${f4(perF)}, ${vi?'sửa đá mịn trước':'fine dress first'}`]});}
 else{const plR=hard?0.004:0.008,plF=0.001,dwell=2;const t=qty*((stock-allow)/plR+allow/plF+dwell/60+0.1);ops.push({kind:'cl',tag:vi?'Ăn ngang (in-feed)':'In-feed (plunge)',passes:1,df:plR,feed:plR,ang:angR,time:t,steps:[`${vi?'Chi tiết có vai: ăn thẳng vào, bánh dẫn nghiêng':'Shouldered part: plunge, reg. wheel tilted'} ${angR}° ${vi?'đẩy vào cữ chặn':'against the end stop'}`,`${vi?'Ăn vào':'Infeed'} ${f4(plR)} in/min ${vi?'thô':'rough'}, ${f4(plF)} ${vi?'tinh':'finish'}, ${vi?'dừng':'dwell'} ${dwell} s`,`${vi?'Bề rộng mài tối đa':'Max ground length'} = ${vi?'bề rộng đá':'wheel width'} ${M.wheelW}"`]});
  ok(vi?'Dài mài':'Ground length',Lp<=M.wheelW,`${Lp} / ${M.wheelW}`);}
 ok(vi?'Cỡ Ø':'Diameter range',d>=(M.minOD||0.06)&&d<=M.maxOD,`Ø${d} (${M.minOD||0.06}–${M.maxOD})`);
 ok(vi?'RPM đá':'Wheel RPM',true,`${sr.rpm} ≤ ${sr.printed} (${sr.sfpm} SFPM)`);
 ok(vi?'Chiều cao tâm':'Work height',true,(vi?`tâm chi tiết cao hơn tâm đá ${h}" (≈ ½ Ø, tối đa 0.5") — cao quá dễ rung, thấp quá chi tiết không tròn`:`work center ${h}" above the wheel line (≈ ½ Ø, max 0.5") — too high chatters, too low gives lobing`));
 ok(vi?'Thanh đỡ':'Work-rest blade',true,blade);
 const time=ops.reduce((a,o)=>a+o.time,0);const J={M,m,hrc,wk,wh,sr,ops,checks,time,rank,auto:!(c.wheel&&GW[c.wheel]),Nr,h,cl:true,hold:vi?'Thanh đỡ + bánh dẫn (không cần mũi tâm)':'Work-rest blade + regulating wheel (no centers)'};
 J.gcode=`(${M.name.toUpperCase().replace(/[()]/g,'').slice(0,40)} - ${vi?'MAY TAY: DUNG BANG CHU TRINH':'MANUAL MACHINE: USE THE CYCLE TABLE'})\n(GRIND WHEEL ${sr.rpm} RPM - REG WHEEL ${Math.round(Nr)} RPM - ANGLE ${angR} / ${angF} DEG)\n(WORK HEIGHT ${h} ABOVE CENTER - ${thru?'THRU-FEED':'IN-FEED'})`;return J;}
