  <div class="card"><h2>${vi?'Các bước mài':'Grinding steps'}</h2>${J.ops.map((o,i)=>`<details class="acc"><summary>${i+1}. ${esc(o.tag)} · ${o.time.toFixed(1)} min</summary><div><ol style="margin:0;padding-left:20px;font-size:13px;line-height:1.5;font-family:ui-monospace,Menlo,monospace">${o.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div></details>`).join('')}</div>
