 const sr=stockRect(),pad=0.3,vb=[sr[0]-pad,sr[1]-pad,sr[2]-sr[0]+2*pad,sr[3]-sr[1]+2*pad],P=l=>l.map((q,i)=>(i?'L':'M')+q[0].toFixed(4)+' '+(-q[1]).toFixed(4)).join('');const sw=vb[2]/300;
