  g.strokeStyle='rgba(60,66,72,.6)';g.lineWidth=2;for(let k=0;k<4;k++){const a=ph+k*Math.PI/2;g.beginPath();g.moveTo(tc[0]+Math.cos(a)*tr*0.5,tc[1]+Math.sin(a)*tr*0.5*ey);g.lineTo(tc[0]+Math.cos(a)*tr*0.97,tc[1]+Math.sin(a)*tr*0.97*ey);g.stroke();}
