 const tp={id:'t'+Date.now().toString(36),name:name||((mat()[LANG==='vi'?'vi':'en'])+' · '+TX[S.fixture.type][LANG==='vi'?1:0]),date:new Date().toISOString().slice(0,10),mat:S.mat,machine:S.machine,def:{...DEF0,...(S.def||{})},fixture:{...S.fixture},opp};
