 S.ops.forEach(o=>{const q=tp.opp[o.type];if(!q)return;TPL_KEYS.forEach(k=>{if(q[k]!==undefined)o[k]=q[k];});if(q.manual){o.auto=false;o.rpm=q.rpm;o.feed=q.feed;o.plunge=q.plunge;}else{o.auto=true;applyFeeds(o);}});
