 if(grid){for(let i=0;i<grid.length;i++){const z=-len+i*LSIM.dz;const r=grid[i];g.fillRect(X(z),Y(r),LSIM.dz*sc+0.6,r*2*sc);}}else{g.fillRect(X(-len),Y(R0),(len+L.faceStock)*sc,R0*2*sc);}
